[{"order":1,"type":"heading","text":"Security and Cryptography in iOS: Keychain, Biometrics, and App Transport Security"},{"order":2,"type":"paragraph","text":"Security is a foundational pillar of iOS development. Protecting user credentials, securing network communications, and leveraging hardware-backed authentication ensure that applications maintain user trust and data integrity. This tutorial explores three critical pillars of iOS security: the Keychain Services API, the LocalAuthentication framework for biometrics, and App Transport Security (ATS)."},{"order":3,"type":"subheading","text":"1. Secure Data Storage with the Keychain"},{"order":4,"type":"paragraph","text":"Never store sensitive data such as passwords, auth tokens, or personally identifiable information in UserDefaults or plain text files. The iOS Keychain provides a secure encrypted container for small pieces of sensitive data."},{"order":5,"type":"code","text":"import Foundation
import Security

class KeychainManager {
    static let shared = KeychainManager()

    func save(key: String, data: Data) -> Bool {
        let query = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrAccount as String: key,
            kSecValueData as String: data
        ] as [String: Any]

        SecItemDelete(query as CFDictionary)
        let status = SecItemAdd(query as CFDictionary, nil)
        return status == errSecSuccess
    }

    func read(key: String) -> Data? {
        let query = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrAccount as String: key,
            kSecReturnData as String: true,
            kSecMatchLimit as String: kSecMatchLimitOne
        ] as [String: Any]

        var item: CFTypeRef?
        let status = SecItemCopyMatching(query as CFDictionary, &item)

        guard status == errSecSuccess else { return nil }
        return item as? Data
    }
}"},{"order":6,"type":"subheading","text":"2. Biometric Authentication with LocalAuthentication"},{"order":7,"type":"paragraph","text":"The LocalAuthentication framework allows you to authenticate users using Touch ID or Face ID. Always check if the device supports biometric evaluation before attempting authentication."},{"order":8,"type":"code","text":"import LocalAuthentication

class BiometricAuthManager {
    func authenticateUser(completion: @escaping (Bool, String?) -> Void) {
        let context = LAContext()
        var error: NSError?

        if context.canEvaluatePolicy(.deviceOwnerAuthenticationWithBiometrics, error: &error) {
            let reason = "Identify yourself to access secure data."

            context.evaluatePolicy(.deviceOwnerAuthenticationWithBiometrics, localizedReason: reason) { success, authenticationError in
                DispatchQueue.main.async {
                    if success {
                        completion(true, nil)
                    } else {
                        let message = authenticationError?.localizedDescription ?? "Authentication failed"
                        completion(false, message)
                    }
                }
            }
        } else {
            let message = error?.localizedDescription ?? "Biometrics not available"
            completion(false, message)
        }
    }
}"},{"order":9,"type":"subheading","text":"3. Network Security with App Transport Security (ATS)"},{"order":10,"type":"paragraph","text":"App Transport Security (ATS) is a privacy feature that forces apps to connect to web services only through secure connections (HTTPS). By default, ATS ensures that all HTTP connections conform to secure best practices."},{"order":11,"type":"bullet_point","text":"All connections must use TLS version 1.2 or later."},{"order":12,"type":"bullet_point","text":"Ciphers are restricted to modern TLS encryption suites with forward secrecy."},{"order":13,"type":"bullet_point","text":"Server certificates must be trusted by the system and signed using valid industry-standard roots."},{"order":14,"type":"paragraph","text":"If you must configure exceptions for specific domains, you can do so in your Info.plist file. However, Apple strongly discourages disabling ATS globally using NSAllowsArbitraryLoads."},{"order":15,"type":"code","text":"<key>NSAppTransportSecurity</key>
<dict>
    <key>NSExceptionDomains</key>
    <dict>
        <key>api.myunsecuresecurement.com</key>
        <dict>
            <key>NSIncludesSubdomains</key>
            <true/>
            <key>NSTemporaryExceptionAllowsInsecureHTTPLoads</key>
            <true/>
            <key>NSTemporaryExceptionMinimumTLSVersion</key>
            <string>TLSv1.1</string>
        </dict>
    </dict>
</dict>"},{"order":16,"type":"subheading","text":"Summary"},{"order":17,"type":"paragraph","text":"By properly implementing Keychain for secure persistence, LocalAuthentication for seamless hardware-backed user verification, and adhering to App Transport Security policies for backend communication, you can build robust and secure iOS applications that protect user data at rest and in transit."}]
